// lint.ts
import { existsSync, statSync } from "node:fs";
import { isAbsolute, join, relative, resolve, sep } from "node:path";

export interface WikilinkIssue {
  raw: string;        // the full [[...]] as written
  target: string;     // extracted file path (docs-relative), "" if none
  kind: "out-of-docs" | "not-found" | "absolute";
}

// Match [[ ... ]]. Non-greedy, no nested brackets. Allows | alias and # anchor inside.
const WIKILINK_RE = /\[\[([^\[\]]+?)\]\]/g;

export function extractWikilinkTargets(text: string): { raw: string; target: string }[] {
  const out: { raw: string; target: string }[] = [];
  for (const m of text.matchAll(WIKILINK_RE)) {
    const raw = m[0];
    const inner = m[1];
    // Strip alias: [[target|alias]] -> target part (before first |)
    // Then strip anchor: [[target#heading]] -> target part (before first #)
    const filePart = inner.split("|")[0].split("#")[0].trim();
    out.push({ raw, target: filePart });
  }
  return out;
}

/**
 * Validate wikilinks in `text`. Links are resolved relative to `docsRoot`
 * (absolute path to the docs/ directory). Returns issues for links that
 * either escape docs/ or point to non-existent files.
 */
export function lintLinks(text: string, docsRoot: string): WikilinkIssue[] {
  const issues: WikilinkIssue[] = [];
  for (const { raw, target } of extractWikilinkTargets(text)) {
    if (target === "") continue; // [[#anchor]] same-file anchor, skip

    if (isAbsolute(target)) {
      issues.push({ raw, target, kind: "absolute" });
      continue;
    }

    const abs = resolve(docsRoot, target);
    const rel = relative(docsRoot, abs);
    // escapes docs/ if it starts with ".." or is on another drive (win)
    if (rel === "" || rel.startsWith(".." + sep) || rel === "..") {
      issues.push({ raw, target, kind: "out-of-docs" });
      continue;
    }

    if (!existsSync(abs) || !statSync(abs).isFile()) {
      issues.push({ raw, target, kind: "not-found" });
    }
  }
  return issues;
}
