import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { readFileSync } from "node:fs";
import { join, resolve, sep } from "node:path";
import { lintLinks, type WikilinkIssue } from "./lint.ts";

const DOCS_DIR = "docs";

interface EditOp { oldText: string; newText: string; }

function applyEdits(original: string, edits: EditOp[]): string {
  let result = original;
  for (const e of edits) {
    // edit tool guarantees oldText is unique; replace first occurrence
    const idx = result.indexOf(e.oldText);
    if (idx === -1) continue; // couldn't locate; skip (the tool itself would error)
    result = result.slice(0, idx) + e.newText + result.slice(idx + e.oldText.length);
  }
  return result;
}

function issueMessage(issues: WikilinkIssue[]): string {
  const lines = issues.map((i) => {
    const why =
      i.kind === "out-of-docs" ? "指向 docs/ 之外——wikilink 仅可引用文档库内的内容"
      : i.kind === "absolute" ? "使用了绝对路径——wikilink 必须相对 docs/"
      : "目标文件不存在";
    return `  • ${i.raw} — ${why}`;
  });
  return [
    "wikilink-lint：以下 wikilink 不合规，已阻断写入：",
    ...lines,
    "请先创建缺失文件、改为指向 docs/ 内已存在的文档，或改用普通文字描述库外内容（如行内代码 `src/...`），然后重试。",
  ].join("\n");
}

export default function (pi: ExtensionAPI) {
  pi.on("tool_call", async (event, ctx) => {
    const toolName: string = event.toolName;
    if (toolName !== "write" && toolName !== "edit") return;

    const input = event.input as { path?: string; content?: string; edits?: EditOp[] };
    const filePath = input.path;
    if (!filePath) return;

    const docsRoot = join(ctx.cwd, DOCS_DIR);
    const absPath = resolve(ctx.cwd, filePath);

    // Only lint markdown files inside docs/
    const relToCwd = relative(ctx.cwd, absPath);
    const inDocs = relToCwd !== "" && !relToCwd.startsWith(".." + sep) && relToCwd !== "..";
    if (!inDocs || !absPath.endsWith(".md")) return;

    let finalText: string;
    if (toolName === "write") {
      finalText = input.content ?? "";
    } else {
      // edit: read current, apply edits
      let current = "";
      try {
        current = readFileSync(absPath, "utf8");
      } catch {
        current = "";
      }
      finalText = applyEdits(current, input.edits ?? []);
    }

    const issues = lintLinks(finalText, docsRoot);
    if (issues.length > 0) {
      return { block: true, reason: issueMessage(issues) };
    }
  });
}
