/**
 * Wikilink linting — pure logic, no pi dependency.
 *
 * Convention enforced by the wikilink-lint extension:
 *   - File references in docs use wikilink syntax: [[path]]
 *   - Paths are relative to the docs/ directory (the "docs root")
 *   - Wikilinks may ONLY point to files inside docs/ (no code, no repo-external)
 *
 * This module is import-safe and unit-testable without the pi runtime.
 */

import { existsSync, statSync } from "node:fs";
import { isAbsolute, relative, resolve, sep } from "node:path";

export type WikilinkIssueKind = "out-of-docs" | "absolute" | "not-found";

export interface WikilinkIssue {
	/** The full wikilink as written, e.g. [[../src/index.ts]]. */
	raw: string;
	/** Extracted docs-relative file path, or "" when there is none. */
	target: string;
	kind: WikilinkIssueKind;
}

/** Matches [[ ... ]]. Inner content may not contain brackets. */
const WIKILINK_RE = /\[\[([^\[\]]+?)\]\]/g;

/**
 * Extract wikilink targets from markdown text.
 *
 * Handles aliases and anchors:
 *   [[a/b.md]]              -> a/b.md
 *   [[a/b.md|Alias]]        -> a/b.md   (alias after first |)
 *   [[a/b.md#Heading]]      -> a/b.md   (anchor after first #)
 *   [[a/b.md#H|Alias]]      -> a/b.md
 *   [[#Heading]]            -> ""        (same-file anchor, no file)
 */
export function extractWikilinkTargets(text: string): { raw: string; target: string }[] {
	const out: { raw: string; target: string }[] = [];
	for (const match of text.matchAll(WIKILINK_RE)) {
		const raw = match[0];
		const inner = match[1];
		// Drop alias (everything after the first |), then drop anchor (after first #).
		const filePart = inner.split("|")[0].split("#")[0].trim();
		out.push({ raw, target: filePart });
	}
	return out;
}

/**
 * Validate every wikilink in `text`.
 *
 * @param text     The (final) markdown content of a docs file.
 * @param docsRoot Absolute path to the docs/ directory. Wikilink paths are
 *                 resolved against this root.
 * @returns Issues for links that escape docs/, use absolute paths, or point
 *          to non-existent (or non-file) targets.
 */
export function lintLinks(text: string, docsRoot: string): WikilinkIssue[] {
	const issues: WikilinkIssue[] = [];

	for (const { raw, target } of extractWikilinkTargets(text)) {
		// [[#anchor]] and [[ |alias]] with no file -> nothing to validate.
		if (target === "") continue;

		if (isAbsolute(target)) {
			issues.push({ raw, target, kind: "absolute" });
			continue;
		}

		const abs = resolve(docsRoot, target);
		const rel = relative(docsRoot, abs);

		// Escaped docs/ (or targets the docs root dir itself).
		if (rel === "" || rel === ".." || rel.startsWith(`..${sep}`)) {
			issues.push({ raw, target, kind: "out-of-docs" });
			continue;
		}

		// Must exist and be a regular file.
		if (!existsSync(abs) || !statSync(abs).isFile()) {
			issues.push({ raw, target, kind: "not-found" });
		}
	}

	return issues;
}

/** Human-readable, LLM-facing message for a set of issues. */
export function describeIssues(issues: WikilinkIssue[]): string {
	const lines = issues.map((issue) => {
		const why =
			issue.kind === "out-of-docs"
				? "指向 docs/ 之外——wikilink 仅可引用文档库内的内容"
				: issue.kind === "absolute"
					? "使用了绝对路径——wikilink 必须相对 docs/"
					: "目标文件不存在";
		return `  • ${issue.raw} — ${why}`;
	});

	return [
		"wikilink-lint：以下 wikilink 不合规，已阻断写入：",
		...lines,
		"请先创建缺失文件、改为指向 docs/ 内已存在的文档，或对库外内容（如代码）改用普通文字 / 行内代码描述，然后重试。",
	].join("\n");
}

/**
 * wikilink-lint — hard-enforce docs wikilink validity.
 *
 * Convention (see docs conventions / archivist agent):
 *   - File references inside docs/ use wikilink syntax [[path]]
 *   - Paths are relative to docs/
 *   - Wikilinks may only point to files inside docs/ (not code, not repo-external)
 *
 * This extension blocks `write` / `edit` tool calls whose resulting docs/*.md
 * content contains a wikilink that escapes docs/ or points to a missing file.
 * It is intentionally non-intrusive: prose paths and Markdown links [t](u)
 * are ignored — only actual [[...]] wikilinks are validated.
 *
 * Hard-block rationale: archivist should create the link target first, then
 * add the link. Blocking enforces that ordering instead of leaving dead links.
 */

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { readFileSync } from "node:fs";
import { join, relative, resolve, sep } from "node:path";
import { describeIssues, lintLinks } from "./lint.ts";

const DOCS_DIR = "docs";

interface EditOp {
	oldText: string;
	newText: string;
}

interface WriteInput {
	path: string;
	content: string;
}

interface EditInput {
	path: string;
	edits: EditOp[];
}

type ToolInput = Partial<WriteInput & EditInput>;

/** Apply edit ops to current content. oldText is unique per edit (tool contract). */
function applyEdits(original: string, edits: EditOp[]): string {
	let result = original;
	for (const op of edits) {
		const idx = result.indexOf(op.oldText);
		if (idx === -1) continue; // unlocatable; the edit tool itself would error
		result = result.slice(0, idx) + op.newText + result.slice(idx + op.oldText.length);
	}
	return result;
}

/** True if `absPath` is a regular file under <cwd>/docs/. */
function isDocsMarkdown(cwd: string, absPath: string): boolean {
	if (!absPath.endsWith(".md")) return false;
	const rel = relative(cwd, absPath);
	return rel !== "" && rel !== ".." && !rel.startsWith(`..${sep}`) && (rel === DOCS_DIR || rel.startsWith(`${DOCS_DIR}${sep}`));
}

export default function (pi: ExtensionAPI) {
	pi.on("tool_call", async (event, ctx) => {
		const toolName: string = event.toolName;
		if (toolName !== "write" && toolName !== "edit") return;

		const input = event.input as ToolInput;
		const filePath: string | undefined = input.path;
		if (!filePath) return;

		const absPath = resolve(ctx.cwd, filePath);
		if (!isDocsMarkdown(ctx.cwd, absPath)) return;

		const docsRoot = join(ctx.cwd, DOCS_DIR);

		let finalText: string;
		if (toolName === "write") {
			finalText = input.content ?? "";
		} else {
			// edit: reconstruct the resulting file content, then lint it.
			let current = "";
			try {
				current = readFileSync(absPath, "utf8");
			} catch {
				current = "";
			}
			finalText = applyEdits(current, input.edits ?? []);
		}

		const issues = lintLinks(finalText, docsRoot);
		if (issues.length > 0) {
			return { block: true, reason: describeIssues(issues) };
		}
	});
}

import { mkdtempSync, mkdirSync, writeFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { extractWikilinkTargets, lintLinks, describeIssues } from "/home/sankabox/code/PiExperiment/.pi/extensions/wikilink-lint/lint.ts";

let failures = 0;
function eq(label: string, actual: unknown, expected: unknown) {
	const a = JSON.stringify(actual);
	const e = JSON.stringify(expected);
	if (a === e) {
		console.log(`  ✓ ${label}`);
	} else {
		failures++;
		console.error(`  ✗ ${label}\n      expected ${e}\n      actual   ${a}`);
	}
}

// Build a fake docs tree.
const docs = mkdtempSync(join(tmpdir(), "wikilint-docs-"));
mkdirSync(join(docs, "architecture"), { recursive: true });
writeFileSync(join(docs, "architecture", "overview.md"), "# Overview");
writeFileSync(join(docs, "tasks.md"), "# Tasks");

// 1. extraction: alias + anchor parsing
eq("extract alias/anchor", extractWikilinkTargets("see [[architecture/overview.md#标题|总览]] and [[tasks.md]]").map((x) => x.target), [
	"architecture/overview.md",
	"tasks.md",
]);

// 2. valid links -> no issues
eq("valid links", lintLinks("x [[architecture/overview.md]] [[tasks.md|tasks]]", docs), []);

// 3. broken link -> not-found
eq("not-found", lintLinks("[[architecture/missing.md]]", docs).map((i) => i.kind), ["not-found"]);

// 4. escapes docs -> out-of-docs
eq("out-of-docs parent", lintLinks("[[../src/index.ts]]", docs).map((i) => i.kind), ["out-of-docs"]);
eq("out-of-docs deep", lintLinks("[[foo/../../../etc/passwd]]", docs).map((i) => i.kind), ["out-of-docs"]);

// 5. absolute path -> absolute
eq("absolute", lintLinks("[[/etc/passwd]]", docs).map((i) => i.kind), ["absolute"]);

// 6. same-file anchor -> skipped (no issue)
eq("same-file anchor", lintLinks("[[#heading]]", docs), []);

// 7. markdown-style link is ignored (not a wikilink)
eq("md link ignored", lintLinks("[text](../src/index.ts)", docs), []);

// 8. directory target -> not a file -> not-found
eq("dir target", lintLinks("[[architecture]]", docs).map((i) => i.kind), ["not-found"]);

// 9. multiple issues reported, ordered
eq(
	"multi issues",
	lintLinks("[[missing.md]] [[../a/b.ts]] [[c.md#x|y]]", docs).map((i) => `${i.kind}:${i.target}`),
	["not-found:missing.md", "out-of-docs:../a/b.ts", "not-found:c.md"],
);

// 10. describeIssues produces a message
const msg = describeIssues(lintLinks("[[missing.md]]", docs));
eq("message mentions link", msg.includes("[[missing.md]]") && msg.includes("阻断"), true);

rmSync(docs, { recursive: true, force: true });
console.log(failures === 0 ? "\nALL PASS" : `\n${failures} FAILED`);
process.exit(failures === 0 ? 0 : 1);

